package testclient

import (
	"fmt"
	"sync"
	"time"

	"github.com/TrebuchetDynamics/gormes-agent/internal/adapters/channels/discord/legacy/protocol"
)

type SendCall struct {
	ChannelID string
	Text      string
}

type EditCall struct {
	ChannelID string
	MessageID string
	Text      string
}

type Client struct {
	mu          sync.Mutex
	selfID      string
	handler     func(protocol.InboundMessage)
	nextMessage int
	texts       []string
	sends       []SendCall
	edits       []EditCall
	typingCalls int
	opened      bool
	closed      bool

	SendErr error
	EditErr error

	SendFn func(channelID, text string) (string, error)
	EditFn func(channelID, messageID, text string) error
}

var _ protocol.Client = (*Client)(nil)

func New(selfID string) *Client {
	return &Client{
		selfID:      selfID,
		nextMessage: 1000,
	}
}

func (c *Client) Open() error {
	c.mu.Lock()
	c.opened = true
	c.mu.Unlock()
	return nil
}

func (c *Client) Close() error {
	c.mu.Lock()
	c.closed = true
	c.mu.Unlock()
	return nil
}

func (c *Client) SelfID() string {
	return c.selfID
}

func (c *Client) SetMessageHandler(handler func(protocol.InboundMessage)) {
	c.mu.Lock()
	c.handler = handler
	c.mu.Unlock()
}

func (c *Client) Send(channelID, text string) (string, error) {
	c.mu.Lock()
	id := fmt.Sprintf("msg-%d", c.nextMessage)
	c.nextMessage++
	c.texts = append(c.texts, text)
	c.sends = append(c.sends, SendCall{ChannelID: channelID, Text: text})
	sendFn := c.SendFn
	sendErr := c.SendErr
	c.mu.Unlock()

	if sendFn != nil {
		return sendFn(channelID, text)
	}
	if sendErr != nil {
		return "", sendErr
	}
	return id, nil
}

func (c *Client) Edit(channelID, messageID, text string) error {
	c.mu.Lock()
	c.texts = append(c.texts, text)
	c.edits = append(c.edits, EditCall{ChannelID: channelID, MessageID: messageID, Text: text})
	editFn := c.EditFn
	editErr := c.EditErr
	c.mu.Unlock()

	if editFn != nil {
		return editFn(channelID, messageID, text)
	}
	if editErr != nil {
		return editErr
	}
	return nil
}

func (c *Client) Typing(string) error {
	c.mu.Lock()
	c.typingCalls++
	c.mu.Unlock()
	return nil
}

func (c *Client) PushMessage(msg protocol.InboundMessage) {
	deadline := time.Now().Add(200 * time.Millisecond)
	for {
		c.mu.Lock()
		handler := c.handler
		c.mu.Unlock()
		if handler != nil {
			handler(msg)
			return
		}
		if time.Now().After(deadline) {
			panic("discord test client handler was not set before PushMessage")
		}
		time.Sleep(time.Millisecond)
	}
}

func (c *Client) SentTexts() []string {
	c.mu.Lock()
	defer c.mu.Unlock()
	out := make([]string, len(c.texts))
	copy(out, c.texts)
	return out
}

func (c *Client) LastSentText() string {
	c.mu.Lock()
	defer c.mu.Unlock()
	if len(c.texts) == 0 {
		return ""
	}
	return c.texts[len(c.texts)-1]
}

func (c *Client) SendCalls() []SendCall {
	c.mu.Lock()
	defer c.mu.Unlock()
	out := make([]SendCall, len(c.sends))
	copy(out, c.sends)
	return out
}

func (c *Client) EditCalls() []EditCall {
	c.mu.Lock()
	defer c.mu.Unlock()
	out := make([]EditCall, len(c.edits))
	copy(out, c.edits)
	return out
}

func (c *Client) TypingCalls() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.typingCalls
}

func (c *Client) Opened() bool {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.opened
}

func (c *Client) Closed() bool {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.closed
}

package streaming

import (
	"errors"
	"testing"
	"time"

	"github.com/TrebuchetDynamics/gormes-agent/internal/adapters/channels/discord/legacy/testclient"
)

func TestCoalescerFlushImmediateEditFailureFallsBackToSend(t *testing.T) {
	mc := testclient.New("bot-1")
	mc.EditErr = errors.New("edit failed")

	c := NewCoalescer(mc, time.Second, "chan-1")
	c.FlushImmediate("⏳")
	c.FlushImmediate("final")

	if got := len(mc.SendCalls()); got != 2 {
		t.Fatalf("send calls = %d, want 2 with fallback send", got)
	}
	if got := len(mc.EditCalls()); got != 1 {
		t.Fatalf("edit calls = %d, want 1", got)
	}
	if got := mc.LastSentText(); got != "final" {
		t.Fatalf("last sent text = %q, want final", got)
	}
}
